import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type InfoboxCardProps = Record<string, any>;

const InfoboxCard: React.FC<InfoboxCardProps> = ({
  backgroundColor = "#e0e5ec",
  transparentBackground = false,
  durationInSeconds = 8,
  titleText = "It's Dark and Hell Is Hot",
  typeText = "Studio album",
  artistName = "DMX",
  releaseDate = "May 19, 1998",
  coverImage = "https://images.unsplash.com/photo-1614613535308-eb5fbd3d2c17?q=80&w=1000&auto=format&fit=crop",
  headerBackgroundColor = "#b0c4de",
}) => {
  
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing calculations
  const minDim = Math.min(width, height);
  const cardWidth = minDim * 0.55; 
  const padding = minDim * 0.01;
  const borderSize = Math.max(1, minDim * 0.002);

  // Animation sequences
  const cardScale = spring({ frame, fps, config: { damping: 14, stiffness: 100 } });
  const cardOpacity = interpolate(frame, [0, 10], [0, 1], { extrapolateRight: "clamp" });

  const headerOpacity = interpolate(frame, [10, 25], [0, 1], { extrapolateRight: "clamp" });
  const headerY = interpolate(frame, [10, 25], [-20, 0], { extrapolateRight: "clamp" });

  const coverOpacity = interpolate(frame, [20, 35], [0, 1], { extrapolateRight: "clamp" });
  const coverScale = interpolate(frame, [20, 35], [0.95, 1], { extrapolateRight: "clamp" });

  const subHeaderOpacity = interpolate(frame, [30, 45], [0, 1], { extrapolateRight: "clamp" });
  const subHeaderY = interpolate(frame, [30, 45], [20, 0], { extrapolateRight: "clamp" });

  const detailsOpacity = interpolate(frame, [40, 55], [0, 1], { extrapolateRight: "clamp" });
  const detailsX = interpolate(frame, [40, 55], [-20, 0], { extrapolateRight: "clamp" });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: 'center', alignItems: 'center', fontFamily: 'Inter', transition: 'none' }}>
      <div style={{
        width: cardWidth,
        backgroundColor: '#f8f9fa',
        border: `${borderSize}px solid #a2a9b1`,
        padding: `${padding}px`,
        display: 'flex',
        flexDirection: 'column',
        gap: `${padding}px`,
        transform: `scale(${cardScale})`,
        opacity: cardOpacity,
        boxShadow: `0 ${minDim * 0.02}px ${minDim * 0.04}px rgba(0,0,0,0.15)`,
        color: '#202122',
        transition: 'none'
      }}>

        {/* Header Banner */}
        <div style={{
          backgroundColor: headerBackgroundColor,
          padding: `${minDim * 0.015}px`,
          textAlign: 'center',
          fontWeight: 700,
          fontStyle: 'italic',
          fontSize: `${minDim * 0.028}px`,
          opacity: headerOpacity,
          transform: `translateY(${headerY}px)`,
          border: `${borderSize}px solid #a2a9b1`,
          transition: 'none'
        }}>
          {titleText}
        </div>

        {/* Album Cover */}
        <img 
          src={coverImage}
          alt={`${titleText} Cover`}
          style={{
            width: '100%',
            aspectRatio: '1 / 1',
            objectFit: 'cover',
            display: 'block',
            opacity: coverOpacity,
            transform: `scale(${coverScale})`,
            border: `${borderSize}px solid #a2a9b1`,
            transition: 'none'
          }}
        />

        {/* Sub-header Banner */}
        <div style={{
          backgroundColor: headerBackgroundColor,
          padding: `${minDim * 0.01}px`,
          textAlign: 'center',
          fontSize: `${minDim * 0.022}px`,
          opacity: subHeaderOpacity,
          transform: `translateY(${subHeaderY}px)`,
          border: `${borderSize}px solid #a2a9b1`,
          transition: 'none'
        }}>
          <span style={{ color: '#0645ad', fontWeight: 600, transition: 'none' }}>{typeText}</span>
          {' by '}
          <span style={{ color: '#0645ad', fontWeight: 600, transition: 'none' }}>{artistName}</span>
        </div>

        {/* Details Section */}
        <div style={{
          padding: `${minDim * 0.005}px`,
          fontSize: `${minDim * 0.022}px`,
          opacity: detailsOpacity,
          transform: `translateX(${detailsX}px)`,
          transition: 'none'
        }}>
          <span style={{ fontWeight: 700, transition: 'none' }}>Released</span> 
          <span style={{ marginLeft: `${minDim * 0.01}px`, transition: 'none'}}>{releaseDate}</span>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default InfoboxCard;